import math


def allocate(total, weights):
    wsum = sum(weights.values())
    raw = {k: total * w / wsum for k, w in weights.items()}
    parts = {k: math.floor(v) for k, v in raw.items()}
    leftover = total - sum(parts.values())
    for k in sorted(raw, key=lambda k: raw[k] - parts[k], reverse=True)[:leftover]:
        parts[k] += 1
    return parts


print(allocate(10, {"easy": 3, "medium": 4.5, "hard": 2.5}))
